{
  "query": "SELECT campaign.id, campaign.name, metrics.impressions, metrics.clicks, metrics.all_conversions, metrics.all_conversions_value, metrics.cost_per_all_conversions, metrics.value_per_all_conversions, metrics.cost_micros FROM campaign WHERE campaign.status = 'PAUSED' AND segments.date DURING LAST_30_DAYS ORDER BY metrics.cost_micros DESC"
}

{
  "query": "SELECT campaign.id, campaign.name, asset_group.id, asset_group_asset.asset_group, asset_group_asset.field_type, asset.text_asset.text, asset.image_asset.full_size.url, asset_group.final_urls FROM asset_group_asset WHERE campaign.id = {{337.campaign.id}} AND asset.text_asset.text IS NOT NULL AND campaign.status = 'PAUSED' AND asset_group.status = 'ENABLED' ORDER BY campaign.id DESC LIMIT 1"
}

{
  "query": "SELECT campaign.id, campaign.name, campaign.status, asset_group.id, asset_group.name, asset_group.status, asset_group.final_urls, asset_group_asset.field_type, asset.image_asset.full_size.url FROM asset_group_asset WHERE campaign.advertising_channel_type = 'PERFORMANCE_MAX' AND asset_group_asset.field_type = 'MARKETING_IMAGE' AND asset_group_asset.asset_group = '{{125.assetGroup.resourceName}}' LIMIT 200"
}

{ 
